import json
import re
from pathlib import Path

data_path = Path("data/trending.json")
with open(data_path, "r", encoding="utf-8-sig") as f:
    data = json.load(f)

def count_words(text):
    words = re.findall(r'\b\w+\b', text)
    return len(words)

